<?php
declare(strict_types=1);
require dirname(__DIR__) . '/common.php';
$actorId = dxf_admin_guard($pdo, DXF_PERMISSION_TEMPLATES);
$id = dxf_positive_id($_GET['id'] ?? 0);
$template = null;
if($id){$statement=$pdo->prepare('SELECT t.*,v.* FROM dxf_templates t LEFT JOIN dxf_template_versions v ON v.id=t.current_version_id WHERE t.id=? LIMIT 1');$statement->execute([$id]);$template=$statement->fetch(PDO::FETCH_ASSOC);if(!is_array($template)){adiwira_render_404();return;}}
$defaultDescriptor=['schema'=>'docx-form/v1','document_filename'=>'completed-document.docx','fields'=>[['key'=>'person.full_name','label'=>'Full name','type'=>'text','required'=>true,'max_length'=>160,'token'=>'{{person.full_name}}','help'=>'','identity'=>'name'],['key'=>'person.email','label'=>'Email address','type'=>'email','required'=>true,'max_length'=>254,'token'=>'{{person.email}}','help'=>'','identity'=>'email']], 'print'=>['title'=>'Completed document','columns'=>1,'show_description'=>true]];
$descriptor=$template?json_decode((string)$template['descriptor_json'],true):$defaultDescriptor;
?>
<div class="dxf-admin"><?php dxf_admin_nav($pdo,$actorId,'new');?><header class="dxf-admin-head"><div><span><?=dxf_h(dxf_t('Immutable revision'))?></span><h1><?=dxf_h($template?dxf_t('Edit template'):dxf_t('New template'))?></h1><p><?=dxf_h(dxf_t('Every save creates a new immutable revision for future submissions.'))?></p></div></header>
<form class="dxf-admin-card dxf-editor" method="post" enctype="multipart/form-data" action="<?=dxf_h(dxf_admin_url('templates/save'))?>">
<input type="hidden" name="csrf_token" value="<?=dxf_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="version" value="<?= (int)($template['version']??0) ?>">
<div class="dxf-admin-grid"><label><?=dxf_h(dxf_t('Title'))?><input class="inp" name="title" maxlength="191" required value="<?=dxf_h($template['title']??'')?>"></label><label><?=dxf_h(dxf_t('Slug'))?><input class="inp" name="slug" maxlength="100" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" required value="<?=dxf_h($template['slug']??'')?>"></label></div>
<label><?=dxf_h(dxf_t('Description'))?><textarea class="inp" name="description" maxlength="2000"><?=dxf_h($template['description']??'')?></textarea></label>
<div class="dxf-admin-grid"><label><?=dxf_h(dxf_t('Status'))?><select class="inp" name="status"><?php foreach(['draft','published','archived'] as $status):?><option value="<?=$status?>" <?=($template['status']??'draft')===$status?'selected':''?>><?=dxf_h(dxf_t(ucfirst($status)))?></option><?php endforeach;?></select></label><label><?=dxf_h(dxf_t('Identity mode'))?><select class="inp" name="identity_mode"><option value="email_otp" <?=($template['identity_mode']??'self_declared')==='email_otp'?'selected':''?>><?=dxf_h(dxf_t('Email OTP'))?></option><option value="self_declared" <?=($template['identity_mode']??'self_declared')==='self_declared'?'selected':''?>><?=dxf_h(dxf_t('Self-declared'))?></option></select></label></div>
<label><?=dxf_h(dxf_t('Descriptor JSON'))?><textarea class="inp dxf-code" name="descriptor_json" rows="24" maxlength="131072" required><?=dxf_h(json_encode($descriptor,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></textarea></label>
<div class="dxf-admin-grid"><label><?=dxf_h(dxf_t('DOCX template'))?><?php if($template):?><small><?=dxf_h(dxf_t('Leave empty to reuse the validated DOCX from the current revision.'))?></small><?php endif;?><input class="inp" type="file" name="docx" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" <?=$template?'':'required'?>></label><label><?=dxf_h(dxf_t('Source PDF'))?><?php if($template):?><small><?=dxf_h(dxf_t('Leave empty to reuse the current source PDF.'))?></small><?php endif;?><input class="inp" type="file" name="source_pdf" accept=".pdf,application/pdf"><span><input type="checkbox" name="remove_source_pdf" value="1"> <?=dxf_h(dxf_t('Remove source PDF'))?></span></label></div>
<fieldset><legend><?=dxf_h(dxf_t('Published capabilities'))?></legend><?php foreach([['allow_source_view','View source PDF'],['allow_source_download','Download source PDF'],['allow_docx_download','Download generated DOCX'],['allow_print','Print approved submission'],['allow_pdf','Optional PDF output']] as [$key,$label]):?><label class="dxf-toggle"><input type="checkbox" name="<?=$key?>" value="1" <?=($template?(int)$template[$key]:in_array($key,['allow_docx_download','allow_print'],true))?'checked':''?>> <?=dxf_h(dxf_t($label))?></label><?php endforeach;?></fieldset>
<p class="dxf-capability"><?=dxf_h(dxf_pdf_converter_available()?dxf_t('A trusted PDF converter is registered.'):dxf_t('PDF remains unavailable until a trusted converter is registered.'))?></p><button class="adam-btn" type="submit"><?=dxf_h(dxf_t('Save new revision'))?></button>
</form></div>
